import java.util.*;
import java.io.*;

public class F3 {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        long n = Long.parseLong(line);
        long result = 0;
        int[] primes = sievePrimes((int)Math.sqrt(n) + 1);
        for (int i = 0; i < primes.length; i++) {
            long val = n / primes[i];
            long count = countPrimesLessThan(val, primes) - (i + 1);
            if (count <= 0) break;
            result += count;
        }
        for (int p : primes) {
            if ((long) p * p * p <= n) result++;
            else break;
        }
        System.out.println(result);
    }

    static int[] sievePrimes(int limit) {
        boolean[] sieve = new boolean[limit + 1];
        Arrays.fill(sieve, true);
        sieve[0] = false; sieve[1] = false;
        for (int i = 2; i * i <= limit; i++) {
            if (sieve[i]) {
                for (int j = i * i; j <= limit; j += i) {
                    sieve[j] = false;
                }
            }
        }
        List<Integer> list = new ArrayList<>();
        for (int i = 2; i <= limit; i++) {
            if (sieve[i]) list.add(i);
        }
        return list.stream().mapToInt(Integer::intValue).toArray();
    }

    static long countPrimesLessThan(long x, int[] primes) {
        long count = 0;
        for (int p : primes) {
            if (p > x) break;
            count++;
        }
        return count;
    }
}
